// TH16 v1.00a st05bs.ecl BossCard2 (main boss, spell 54) + BossCard2B (B boss, spell 58).
// Both entries run inside one 2400-frame spell window; see report.md for the cross-enemy
// enmCall(BossCard1Hide) handoff note.

const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// Approved TH16 aliases (bullet-types.md, 2026-11-07).
const TH16_STAR_R: int = 608;
const TH16_TALISMAN: int = 528;

// st05bs.ecl.txt BossCard2_at 2012-2013: etSprite(0,16,10); BossCard2B_at 1915+1937-1940:
// etSprite(0,12,10) then EX SETSPRITE a=11,b=0x8004 -> talisman/color 4.
const COLOR_STAR: int = 10;
const COLOR_TALISMAN: int = 4;

// ---------------------------------------------------------------------------
// BossCard2_at EX layout (per fired bullet, records 0..12):
//   ANIM a=1 (birth offset -4v), then six (STEP a=$B c=0 r=+-30deg, ANGLE_ACCEL a=$B s=+-0.5deg/f)
//   pairs. The STEP pair runs with its ANGLE_ACCEL; the next STEP waits for that pair.
// Target: six equal-purpose segments; the loop body carries two segments, so a bullet
// keeps two sampled durations (n1,n2) repeated three times instead of six independent ones.
xformdef CARD2_STAR(n1: int, n2: int, v: fx) {
again:
    set_accel(0fx - v / (n1 as fx));
    set_ang_vel(0.5deg);
    wait(n1);
    turn(-30deg);
    set_speed(v);
    set_accel(0fx - v / (n2 as fx));
    set_ang_vel(-0.5deg);
    wait(n2);
    turn(30deg);
    set_speed(v);
    loop(again, 3);
    set_accel(0fx);
    set_ang_vel(0deg);
}

// BossCard2B_at 1913-1950: ANIM a=1, ACCEL a=120 r=0.01 s=-999999 (fixed downward vector),
// BOUNCE a=1 b=2(D) r=1.0, SETSPRITE a=11 b=0x8004, STEP a=1 b=1 c=1 s=1.0/1.8.
// STEP c=1 re-checks the player at the segment boundary one frame after spawn and restores
// the target speed there.
xformdef CARD2B_BULLET(s: fx) {
    bounce_arm(8, 1);
    set_gravity(0fx, 0.01fx);
    wait(1);
    aim_player(0deg);
    set_speed(s);
    wait(119);
    set_gravity(0fx, 0fx);
}

// ---------------------------------------------------------------------------
// moveRand(120, 0, 0.4) shared helper (movement.md recipe, limit center (0,128) 240x64).
// int slot 0 = next-step counter; fx slots 0/1 = logical unit direction.
sub mr_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var sp: fx = 0fx;
    if k < 120 { sp = ((120 - k) as fx) / 120fx * 0.4fx; }
    var nx: fx = $self_x + self_fx(0) * sp;
    var ny: fx = $self_y + self_fx(1) * sp;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub mr_begin(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    mr_arm_next_step();
}

sub mr_pick() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    mr_begin(a as angle);
}

sub mr_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        mr_arm_next_step();
    }
}

// ---------------------------------------------------------------------------
// BossCard2_at 2012-2096: one bullet per emission, angle 90deg from the top edge,
// etOffsetAbs x = RANDF2 * -192. Two emissions per loop, waits 6/6 (Easy) or 2/3 (Lunatic).
async sub fire_main() {
    var v: fx = 2.0fx;
    var w1: int = 6;
    var w2: int = 6;
    if global(GVAR_RANK) >= RANK_HARD {
        v = 2.5fx;
        w1 = 2;
        w2 = 3;
    }
    var y: fx = 0fx - 4fx * v;
    loop {
        var n1: int = rand(60) + 60;
        var n2: int = rand(60) + 60;
        var x: fx = ((rand(65536) - 32768) as fx) / 32768 * -192fx;
        _ = fire(TH16_STAR_R, COLOR_STAR, x, y, v, 90deg, CARD2_STAR(n1, n2, v), none);
        wait(w1);
        n1 = rand(60) + 60;
        n2 = rand(60) + 60;
        x = ((rand(65536) - 32768) as fx) / 32768 * -192fx;
        _ = fire(TH16_STAR_R, COLOR_STAR, x, y, v, 90deg, CARD2_STAR(n1, n2, v), none);
        wait(w2);
    }
}

// BossCard2B_at 1955-2004: four emissions per loop at fixed x patterns, one RANDF2 each.
// E/N one layer at speed0; H/L two layers at speed0 and 1.8.
async sub fire_b() {
    var s0: fx = 2.0fx;
    var s1: fx = 1.8fx;
    var layers: int = 1;
    var wt: int = 20;
    var sv: fx = 1.0fx;
    if global(GVAR_RANK) >= RANK_HARD {
        s0 = 3.5fx;
        layers = 2;
        wt = 8;
        sv = 1.8fx;
    }
    var y0: fx = 0fx - 4fx * s0;
    var y1: fx = 0fx - 4fx * s1;
    loop {
        var x: fx = ((rand(65536) - 32768) as fx) / 32768 * 192fx;
        _ = fire(TH16_TALISMAN, COLOR_TALISMAN, x, y0, s0, 90deg, CARD2B_BULLET(sv), none);
        if layers == 2 {
            _ = fire(TH16_TALISMAN, COLOR_TALISMAN, x, y1, s1, 90deg, CARD2B_BULLET(sv), none);
        }
        wait(wt);

        x = ((rand(65536) - 32768) as fx) / 32768 * 64fx - 128fx;
        _ = fire(TH16_TALISMAN, COLOR_TALISMAN, x, y0, s0, 90deg, CARD2B_BULLET(sv), none);
        if layers == 2 {
            _ = fire(TH16_TALISMAN, COLOR_TALISMAN, x, y1, s1, 90deg, CARD2B_BULLET(sv), none);
        }
        wait(wt);

        x = ((rand(65536) - 32768) as fx) / 32768 * 64fx + 128fx;
        _ = fire(TH16_TALISMAN, COLOR_TALISMAN, x, y0, s0, 90deg, CARD2B_BULLET(sv), none);
        if layers == 2 {
            _ = fire(TH16_TALISMAN, COLOR_TALISMAN, x, y1, s1, 90deg, CARD2B_BULLET(sv), none);
        }
        wait(wt);

        x = ((rand(65536) - 32768) as fx) / 32768 * 64fx;
        _ = fire(TH16_TALISMAN, COLOR_TALISMAN, x, y0, s0, 90deg, CARD2B_BULLET(sv), none);
        if layers == 2 {
            _ = fire(TH16_TALISMAN, COLOR_TALISMAN, x, y1, s1, 90deg, CARD2B_BULLET(sv), none);
        }
        wait(wt);
    }
}

// ---------------------------------------------------------------------------
// Shared card entry (st05bs.ecl.txt 1785-1827 / 1852-1894): clear of the previous segment,
// timerReset, movePosTime(60,4,0,128), moveLimit(0,128,240,64), then the +120 block starts
// the firing task and the anm316/wait160/moveRand120/wait160 movement loop.
async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    set_self_int(0, 0);
    move_vel(0, 90deg, 0fx, EASE_LINEAR);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(120);
    spawn fire_main();
    loop {
        mr_wait(160);
        mr_pick();
        mr_wait(160);
    }
}

async sub bossb_main() {
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    set_self_int(0, 0);
    move_vel(0, 90deg, 0fx, EASE_LINEAR);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(120);
    spawn fire_b();
    loop {
        mr_wait(160);
        mr_pick();
        mr_wait(160);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2000, 0, 0, 1, boss_main);
    _ = spawn_enemy(0fx, 128fx, 2000, 0, 0, 2, bossb_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
